// Turn optional filters into a Qdrant filter. Comma-separated values match any of them.
const req = $('Tool request').first().json;
const vector = $input.first().json.embeddings[0];
const fields = { employer: 'employer', domain: 'domain', skill: 'skills', tool_name: 'tools', content_type: 'content_type' };
const must = [];
for (const [input, key] of Object.entries(fields)) {
  const values = String(req[input] || '').split(',').map((v) => v.trim().toLowerCase()).filter(Boolean);
  if (values.length === 1) must.push({ key: `metadata.${key}`, match: { value: values[0] } });
  if (values.length > 1) must.push({ key: `metadata.${key}`, match: { any: values } });
}
return [{ json: { query: vector, limit: 30, with_payload: true, ...(must.length ? { filter: { must } } : {}) } }];

// Group chunks by document, keep the best score, and prefer originals over copies.
const req = $('Tool request').first().json;
const limit = Math.min(Math.max(parseInt(req.limit, 10) || 5, 1), 10);
const points = ($input.first().json.result || {}).points || [];
const docs = new Map();
for (const p of points) {
  const m = (p.payload || {}).metadata || {};
  if (!docs.has(m.doc_id)) {
    docs.set(m.doc_id, {
      doc_id: m.doc_id, title: m.title, url: m.url || m.github_url, content_type: m.content_type,
      employer: m.employer || undefined, domain: m.domain, skills: m.skills || undefined, tools: m.tools || undefined,
      last_reviewed: m.last_reviewed || undefined, stale: m.stale || undefined,
      canonical: m.canonical || undefined, score: Math.round(p.score * 1000) / 1000, excerpts: [],
    });
  }
  const d = docs.get(m.doc_id);
  if (d.excerpts.length < 2) d.excerpts.push(String(p.payload.content || '').replace(/\s+/g, ' ').slice(0, 600));
}
let results = [...docs.values()];
const ids = new Set(results.map((d) => d.doc_id));
// A copy whose original is also in the results is dropped. Otherwise it stays, with a pointer to the original.
results = results.filter((d) => !d.canonical || ![].concat(d.canonical).some((c) => ids.has(c)));
for (const d of results) if (d.canonical) d.note = `Restates ${[].concat(d.canonical).join(', ')}. Prefer the original when citing.`;
return [{ json: {
  query: req.query,
  filters: Object.fromEntries(['employer', 'domain', 'skill', 'tool_name', 'content_type'].filter((k) => req[k]).map((k) => [k, req[k]])),
  results: results.slice(0, limit),
  hint: results.length ? 'Cite the url. Call get_document with a doc_id for the full text.' : 'No match. Try fewer filters or other words.',
} }];

// Only documents that passed the quality gate are in Qdrant. Anything else is not served.
const req = $('Tool request').first().json;
const point = (($input.first().json.result || {}).points || [])[0];
if (!point) {
  return [{ json: { found: false, doc_id: req.doc_id } }];
}
const m = point.payload.metadata;
const [, owner, repo, branch, path] = m.github_url.match(/^https:\/\/github\.com\/([^/]+)\/([^/]+)\/blob\/([^/]+)\/(.+)$/);
return [{ json: { found: true, meta: m, api_url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURI(path)}?ref=${branch}` } }];

const check = $('Check stored').first().json;
if (!check.found) {
  return [{ json: { error: `Not available: ${check.doc_id}. Only indexed documents can be read. Use search_evidence to find a doc_id (format source:path).` } }];
}
const m = check.meta;
const text = $input.first().json.data;
if (typeof text !== 'string') return [{ json: { error: `Could not read ${m.doc_id} from GitHub. Try again later.` } }];
return [{ json: {
  doc_id: m.doc_id, title: m.title, url: m.url || m.github_url, github_url: m.github_url,
  content_type: m.content_type, employer: m.employer || undefined, last_reviewed: m.last_reviewed || undefined,
  stale: m.stale || undefined, canonical: m.canonical || undefined, content: text,
} }];
